"""Pre-commit hook installation and management for GitSentinel."""

import os
import stat
from pathlib import Path
from typing import Tuple

HOOK_SCRIPT = """#!/usr/bin/env sh
# GitSentinel pre-commit security gate
# Automatically generated by: gitsentinel install-hook

python -m gitsentinel.cli scan --fail-on-critical
EXIT_CODE=$?

if [ $EXIT_CODE -ne 0 ]; then
    echo ""
    echo "❌ GitSentinel: Commit blocked due to critical security or bloat issues."
    echo "💡 Fix the reported issues above or run with --no-verify to bypass."
    exit 1
fi

exit 0
"""

def install_pre_commit_hook(repo_dir: Path) -> Tuple[bool, str]:
    """Installs pre-commit hook into .git/hooks/."""
    git_dir = repo_dir / ".git"
    if not git_dir.exists():
        return False, "Not a git repository. Run 'git init' first."

    hooks_dir = git_dir / "hooks"
    hooks_dir.mkdir(parents=True, exist_ok=True)

    hook_file = hooks_dir / "pre-commit"

    try:
        hook_file.write_text(HOOK_SCRIPT, encoding="utf-8")
        # Set executable permissions (important on Unix/macOS/WSL)
        st = os.stat(hook_file)
        os.chmod(hook_file, st.st_mode | stat.S_IEXEC | stat.S_IXGRP | stat.S_IXOTH)
        return True, f"Git pre-commit hook successfully installed at: {hook_file}"
    except OSError as e:
        return False, f"Failed to install hook: {e}"
